 3	public final class BubbleSort {
 4	
 5	    private BubbleSort() {
 6	        // Utility class.
 7	    }
 8	
 9	    public static void sortInPlace(int[] values) {
10	        validate(values);
11	        sortValuesInPlace(values);
12	    }
13	
14	    public static int[] sortedCopy(int[] values) {
15	        validate(values);
16	
17	        int[] copy = Arrays.copyOf(values, values.length);
18	        sortValuesInPlace(copy);
19	        return copy;
20	    }
21	
22	    private static void validate(int[] values) {
23	        if (values == null) {
24	            throw new IllegalArgumentException("values must not be null");
25	        }
26	    }
27	
28	    private static void sortValuesInPlace(int[] values) {
29	        int end = values.length - 1;
30	        while (end > 0) {
31	            int lastSwapIndex = bubblePass(values, end);
32	            if (lastSwapIndex == 0) {
33	                return;
34	            }
35	            end = lastSwapIndex - 1;
36	        }
37	    }
38	
39	    private static int bubblePass(int[] values, int endExclusive) {
40	        int lastSwapIndex = 0;
41	
42	        for (int index = 0; index < endExclusive; index++) {
43	            if (isOutOfOrder(values, index)) {
44	                swap(values, index, index + 1);
45	                lastSwapIndex = index + 1;
46	            }
47	        }
48	
49	        return lastSwapIndex;
50	    }
51	
52	    private static boolean isOutOfOrder(int[] values, int index) {
53	        return values[index] > values[index + 1];
54	    }
55	
56	    private static void swap(int[] values, int leftIndex, int rightIndex) {
57	        int temp = values[leftIndex];
58	        values[leftIndex] = values[rightIndex];
59	        values[rightIndex] = temp;
60	    }
61	}

